#include <string>
#include <algorithm>

class Solution {
public:
    int minOpsRotatedPalindromeOptimal(std::string s) {
        int n = s.size();
        int best = n;
        std::string doubled = s + s;
        for (int shift = 0; shift < n; ++shift) {
            int diffs = 0;
            for (int i = 0; i < n / 2; ++i) {
                if (doubled[shift + i] != doubled[shift + n - 1 - i]) diffs++;
            }
            best = std::min(best, diffs);
        }
        return best;
    }
};

class Solution {
    public int minOpsRotatedPalindromeOptimal(String s) {
        int n = s.length();
        int best = n;
        String doubled = s + s;
        for (int shift = 0; shift < n; shift++) {
            int diffs = 0;
            for (int i = 0; i < n / 2; i++) {
                if (doubled.charAt(shift + i) != doubled.charAt(shift + n - 1 - i)) diffs++;
            }
            best = Math.min(best, diffs);
        }
        return best;
    }
}

function minOpsRotatedPalindromeOptimal(s) {
    const n = s.length;
    let best = n;
    const doubled = s + s;
    for (let shift = 0; shift < n; shift++) {
        let diffs = 0;
        for (let i = 0; i < Math.floor(n / 2); i++) {
            if (doubled[shift + i] !== doubled[shift + n - 1 - i]) diffs++;
        }
        best = Math.min(best, diffs);
    }
    return best;
